def numIslands(grid):
    if not grid or not grid[0]: return 0
    grid = [list(r) for r in grid]
    m, n = len(grid), len(grid[0])
    count = 0
    def dfs(r, c):
        if 0 <= r < m and 0 <= c < n and grid[r][c] == '1':
            grid[r][c] = '0'
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    for r in range(m):
        for c in range(n):
            if grid[r][c] == '1':
                count += 1
                dfs(r, c)
    return count

reference_solutions.optimal_python:
def numIslands(grid):
    if not grid or not grid[0]: return 0
    grid = [list(r) for r in grid]
    m, n = len(grid), len(grid[0])
    count = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == '1':
                count += 1
                q = [(r, c)]
                grid[r][c] = '0'
                while q:
                    cr, cc = q.pop(0)
                    for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == '1':
                            grid[nr][nc] = '0'
                            q.append((nr, nc))
    return count

